import { useState, useMemo } from 'react';
import {
  Card,
  Stack,
  TextField,
  Select,
  SelectOption,
  Switch,
  Button,
  Alert,
  Text,
} from '@jinx-ui/react';

const ROLE_OPTIONS: { value: string; label: string }[] = [
  { value: 'member', label: 'Участник' },
  { value: 'admin', label: 'Администратор' },
  { value: 'viewer', label: 'Наблюдатель' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('member');
  const [notify, setNotify] = useState(true);
  const [touched, setTouched] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const isEmailValid = useMemo(() => EMAIL_PATTERN.test(email.trim()), [email]);
  const showError = touched && !isEmailValid;

  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!isEmailValid) return;
    setSubmitted(true);
  }

  return (
    <Stack direction="column" gap="md" className="jx-max-w-sm">
      {submitted && (
        <Alert
          variant="success"
          onClose={() => setSubmitted(false)}
        >
          Приглашение отправлено на {email}
        </Alert>
      )}

      <Card padding="lg">
        <form onSubmit={handleSubmit}>
          <Stack direction="column" gap="md">
            <Stack direction="column" gap="xs">
              <TextField
                label="Email"
                type="email"
                value={email}
                onChange={(event) => setEmail(event.target.value)}
                onBlur={() => setTouched(true)}
                placeholder="name@company.com"
                error={showError}
                required
              />
              <Text
                size="sm"
                color={showError ? 'var(--jx-color-danger)' : 'var(--jx-color-text-secondary)'}
              >
                {showError
                  ? 'Введите корректный email, например name@company.com'
                  : 'На этот адрес придёт приглашение в команду'}
              </Text>
            </Stack>

            <Select
              label="Роль"
              value={role}
              onChange={(value) => setRole(value)}
            >
              {ROLE_OPTIONS.map((option) => (
                <SelectOption key={option.value} value={option.value}>
                  {option.label}
                </SelectOption>
              ))}
            </Select>

            <Switch
              checked={notify}
              onChange={(checked) => setNotify(checked)}
              label="Отправить уведомление"
            />

            <Button type="submit" disabled={!isEmailValid} variant="primary">
              Отправить приглашение
            </Button>
          </Stack>
        </form>
      </Card>
    </Stack>
  );
}

export default TeamInviteForm;

